#!/usr/bin/env node
// Generated by scripts/build-skill.mjs from scripts/skill/save_github.mjs in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
// Save a drawcast to a public GitHub repository of the user's and print the
// drawcast.app link that plays it from there — a link that lasts and stays short.
//
//   node save_github.mjs cast.yaml OWNER/REPO [--dir casts] [--name my-cast]
//
// It uses the GitHub CLI (`gh`), signed in as the user: nothing else needs a
// key. It never overwrites a file: a name already taken in the folder gets
// -2, -3 … The repository must be public, because the player reads the file
// the way anyone on the web can. Node's standard library and `gh` only.
import { spawnSync } from "node:child_process";
import { readFileSync, realpathSync } from "node:fs";
import { extname } from "node:path";
import { fileURLToPath } from "node:url";

const PLAYER = "https://www.drawcast.app/";
const EXT_RE = /^\.(cast|ya?ml|json|txt)$/;
const REPO_RE = /^[\w.-]+\/[\w.-]+$/;

/** `gh` with `args`, `input` on stdin: {status, stdout, stderr}. */
export function runGh(args, input) {
  const r = spawnSync("gh", args, { input, encoding: "utf8" });
  if (r.error) return { status: 127, stdout: "", stderr: String(r.error.message) };
  return { status: r.status ?? 1, stdout: r.stdout ?? "", stderr: r.stderr ?? "" };
}

/** A file name from the drawcast's title: lower case, letters, digits and dashes, at most 60 characters. */
export function slugOf(title) {
  const s = String(title ?? "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60)
    .replace(/-+$/, "");
  return s || "drawcast";
}

/** The drawcast's title: a YAML spec's or playlist's `title:`, else a script's first `# heading`. */
export function titleOf(text) {
  const yaml = /^\s*title:\s*["']?(.+?)["']?\s*$/m.exec(text);
  if (yaml) return yaml[1];
  const heading = /^#\s+(.+)$/m.exec(text);
  return heading ? heading[1].trim() : "";
}

/** The folder, cleaned: no leading or trailing slash, no `..`. */
function cleanDir(dir) {
  const d = String(dir ?? "").replace(/^\/+|\/+$/g, "");
  if (d.split("/").some((p) => p === ".." || p === ".")) throw new Error(`--dir ${dir}: a folder inside the repository, please`);
  if (d && !/^[\w./-]+$/.test(d)) throw new Error(`--dir ${dir}: letters, digits, dashes, dots and slashes only`);
  return d;
}

/**
 * Saves `text` as `<dir>/<name><ext>` in `repo` and answers the player link.
 * `gh` is runGh, or a stand-in for tests.
 */
export function saveToGitHub({ text, ext, repo, dir = "casts", name, gh = runGh }) {
  if (!text || !text.trim()) throw new Error("The drawcast is empty.");
  if (!EXT_RE.test(ext)) throw new Error(`A drawcast file ends in .yaml, .cast or .json, not "${ext}".`);
  if (!REPO_RE.test(repo ?? "")) throw new Error(`"${repo}" is not OWNER/REPO.`);
  const folder = cleanDir(dir);

  const who = gh(["api", "user", "--jq", ".login"]);
  if (who.status !== 0) throw new Error("The GitHub CLI is not signed in: ask the user to run `gh auth login`, then try again.");

  const info = gh(["api", `repos/${repo}`, "--jq", ".private"]);
  if (info.status !== 0) {
    throw new Error(`${repo} was not found (or ${who.stdout.trim()} cannot see it). To make it, with the user's yes: gh repo create ${repo} --public`);
  }
  if (info.stdout.trim() === "true") throw new Error(`${repo} is private: the player reads the file as anyone on the web would, so it needs a public repository.`);

  const base = slugOf(name || titleOf(text));
  let path = "";
  for (let i = 1; i <= 50; i++) {
    const file = `${base}${i === 1 ? "" : `-${i}`}${ext}`;
    const candidate = folder ? `${folder}/${file}` : file;
    if (gh(["api", `repos/${repo}/contents/${candidate}`, "--jq", ".sha"]).status !== 0) {
      path = candidate;
      break;
    }
  }
  if (!path) throw new Error(`Fifty files named ${base} already: pass --name.`);

  const body = JSON.stringify({ message: `drawcast: ${titleOf(text) || base}`.slice(0, 120), content: Buffer.from(text, "utf8").toString("base64") });
  const put = gh(["api", "-X", "PUT", `repos/${repo}/contents/${path}`, "--input", "-"], body);
  if (put.status !== 0) throw new Error(`GitHub refused the file: ${put.stderr.trim() || put.stdout.trim()}`);
  return { path, link: `${PLAYER}#gh=${repo}/${path}` };
}

function main(argv) {
  const args = [...argv];
  const flag = (n) => {
    const at = args.indexOf(n);
    if (at === -1) return undefined;
    const v = args[at + 1];
    args.splice(at, 2);
    return v;
  };
  const dir = flag("--dir");
  const name = flag("--name");
  const [file, repo] = args;
  if (!file || !repo) {
    console.error("usage: node save_github.mjs cast.yaml OWNER/REPO [--dir casts] [--name my-cast]");
    return 2;
  }
  let bytes = readFileSync(file);
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) bytes = bytes.subarray(3);
  const text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  try {
    const { path, link } = saveToGitHub({ text, ext: extname(file).toLowerCase(), repo, dir: dir ?? "casts", name });
    console.log(link);
    console.error(`saved as ${repo}/${path} — the link plays it for anyone; an edit to the file shows within a few minutes`);
    return 0;
  } catch (err) {
    console.error(err.message);
    return 1;
  }
}

if (process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))) process.exitCode = main(process.argv.slice(2));
